const config = $('Build Run Config').item.json;
const health = $('Check FastAPI Health').item.json;
const integrations = $('Check Integration Keys').item.json;
const vm = $('Check VM Status').item.json;
const stdout = vm.stdout || '';
const diskLine = stdout.split('\n').find((line) => line.includes('/dev/root')) || '';
const diskMatch = diskLine.match(/\s(\d+)G\s+\d+G\s+(\d+)G\s+(\d+)%/);
const freeGb = diskMatch ? Number(diskMatch[2]) : null;
const usedPct = diskMatch ? Number(diskMatch[3]) : null;
const providerRows = Array.isArray(integrations.integrations) ? integrations.integrations : [];
const configuredIntegrations = providerRows.filter((item) => item.configured).map((item) => item.name);
const issues = [];
if (health.ok !== 'true' && health.ok !== true) issues.push('FastAPI health did not return ok=true.');
if (!vm.ok) issues.push('VM status endpoint returned ok=false.');
if (freeGb !== null && freeGb < config.minimumFreeGb) issues.push(`VM free storage ${freeGb}GB is below ${config.minimumFreeGb}GB gate.`);
if (freeGb === null) issues.push('Could not parse VM disk free storage from /vm/status.');
return [{
  json: {
    ok: issues.length === 0,
    decision: issues.length === 0 ? 'READY_FOR_SMALL_BATCH' : 'STOP_AND_FIX',
    checkedAt: config.checkedAt,
    vm: { user: config.vmUser, host: config.vmHost, freeGb, usedPct, diskLine },
    configuredIntegrations,
    issues,
    next: issues.length === 0 ? 'Import/run Timestamp_msi ADV storage-safe GDC batch loop.' : 'Free VM storage or fix failed service checks before download/training.'
  }
}];
